import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const NAV = [
  { to: "/dashboard", label: "Dashboard" },
  { to: "/directory", label: "Directory" },
  { to: "/mentorship", label: "Mentorship" },
  { to: "/jobs", label: "Opportunities" },
  { to: "/messages", label: "Messages" },
];

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const handleLogout = async () => { await logout(); navigate("/"); };

  return (
    <header style={{ background: "rgba(253,251,247,.9)", borderBottom: "1px solid var(--border)", position: "sticky", top: 0, zIndex: 50, backdropFilter: "blur(10px)" }}>
      <div style={{ maxWidth: 1200, margin: "0 auto", padding: "1rem 2rem", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <Link to={user ? "/dashboard" : "/"} style={{ textDecoration: "none", display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 36, height: 36, background: "var(--ivy)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Cormorant Garamond" }}>A</div>
          <div>
            <div className="font-serif" style={{ fontSize: 20, color: "var(--ivy)" }}>Alumnae</div>
            <div className="overline">College Network</div>
          </div>
        </Link>
        {user && (
          <nav style={{ display: "flex", gap: 4 }}>
            {NAV.map(n => <Link key={n.to} to={n.to} style={{ padding: "8px 16px", textDecoration: "none", color: "var(--muted)", fontSize: 14 }}>{n.label}</Link>)}
          </nav>
        )}
        <div>
          {!user ? (
            <>
              <Link to="/login" style={{ marginRight: 12 }}>Sign In</Link>
              <Link to="/register"><button className="btn-primary">Join Network</button></Link>
            </>
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <Link to="/profile">{user.name}</Link>
              <button className="btn-outline" onClick={handleLogout}>Sign Out</button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}
